{"implementation":"def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    edges = []
    for u, v, d in distances:
        w = max(core[u], core[v], d)
        edges.append((w, u, v))
    # Sort by weight, then lexicographically by nodes
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        # Union by size: not necessary for correctness but implement for balance
        # Use rank dict for deterministic tie-breaking: smaller node becomes root
        if rx < ry:
            parent[ry] = rx
        else:
            parent[rx] = ry
        return True
    mst = []
    for w, u, v in edges:
        if union(u, v):
            # Ensure deterministic ordering of nodes in edge
            if u < v:
                mst.append([u, v, w])
            else:
                mst.append([v, u, w])
            if len(mst) == n - 1:
                break
    # Final sort to guarantee stable output
    mst.sort(key=lambda e: (e[2], e[0], e[1]))
    return {'edges': mst}"}
